-- 0010_collections: collection records with drafts, versions, references and redirects (task A8).
--
-- Additive only: four new tables and a seed generated from src/data/catalog.ts
-- (scripts/content/generate-seed.mjs): 4 circuits, 15 destinations, 22 tours
-- and the FAQ group every tour shares, each published as version 1 with the
-- content the site shows today. Nothing on the public site reads these tables
-- yet (task B5).
--
--   collection_items          one row per record; `draft` is the editable copy,
--                             `status` draft, published or hidden; trash is
--                             `deleted_at` (restorable for 30 days)
--   collection_item_versions  published copies, the newest 30 kept
--   content_refs              who points at what (records, later pages and
--                             sections); a record pointed at cannot be deleted
--   redirects                 old public paths after a published key change

create table if not exists collection_items (
  id text primary key,
  collection text not null,
  key text not null,
  position integer not null default 0,
  status text not null default 'draft',
  draft jsonb not null,
  rev integer not null default 1,
  published_version_id text,
  created_at timestamptz not null default now(),
  created_by text,
  updated_at timestamptz not null default now(),
  updated_by text,
  deleted_at timestamptz,
  deleted_by text,
  constraint collection_items_status_check check (status in ('draft', 'published', 'hidden')),
  constraint collection_items_live_has_version check (status = 'draft' or published_version_id is not null)
);

create unique index if not exists collection_items_key_idx on collection_items (collection, key);
create index if not exists collection_items_list_idx on collection_items (collection, position) where deleted_at is null;

create table if not exists collection_item_versions (
  id text primary key,
  item_id text not null references collection_items (id),
  version integer not null,
  data jsonb not null,
  published_at timestamptz not null default now(),
  published_by text,
  constraint collection_item_versions_unique unique (item_id, version)
);

create table if not exists content_refs (
  id text primary key,
  from_kind text not null,
  from_id text not null,
  from_state text not null,
  to_kind text not null,
  to_id text not null,
  field text,
  created_at timestamptz not null default now(),
  constraint content_refs_state_check check (from_state in ('draft', 'published'))
);

create index if not exists content_refs_to_idx on content_refs (to_kind, to_id);
create index if not exists content_refs_from_idx on content_refs (from_kind, from_id);

create table if not exists redirects (
  id text primary key,
  from_path text not null,
  to_path text not null,
  status_code integer not null default 301,
  source_kind text,
  source_id text,
  created_at timestamptz not null default now(),
  created_by text,
  constraint redirects_status_check check (status_code in (301, 308)),
  constraint redirects_not_self check (from_path <> to_path)
);

create unique index if not exists redirects_from_idx on redirects (from_path);

