  ('aec6f243-7e07-582d-bad5-78196bdf4251', 'faq-groups', 'tour-shared', 0, 'published', '{"key":"tour-shared","name":"Questions every tour shows","items":[{"q":"Are prices listed online?","a":"Published rates are quote-based. Request a quote or start a booking enquiry and the team will confirm current pricing."},{"q":"Do I need a yellow fever certificate?","a":"A yellow fever vaccination certificate is required if traveling to and from certain areas. Confirm current entry rules before you fly."},{"q":"Is this a guaranteed departure?","a":"Departures depend on availability and group size. Seats are held for 15 minutes; a booking is confirmed only after a verified payment event."},{"q":"Can I book as a guest?","a":"Yes. An account is optional. After confirmation you can sign in to keep vouchers and future trips in one place."}]}'::jsonb, 1, '43107d9e-89b7-5359-9a16-75991021e657'),
  ('c7155fb7-52a0-5bcb-9ca5-92a938d05708', 'tours', 'freetown-city-tour', 0, 'published', '{"slug":"freetown-city-tour","title":"Freetown City Tour","country":"sierra-leone","circuit":"western-circuit","destinationSlug":"freetown","duration":"Half day","durationDays":1,"category":"culture","difficulty":"easy","groupMin":1,"groupMax":12,"languages":["English"],"summary":"A guided introduction to Freetown’s Krio heritage, harbour, and city landmarks, the same city tours Tourism Is Life is known for.","highlights":["Krio heritage walk","Harbour and city viewpoints","Local food stop"],"inclusions":[{"claim":"Licensed guide","sourceUrl":"","sourceDate":"","fallback":""},"Ground transport in Freetown","Bottled water"],"exclusions":["Meals not listed","Personal purchases","Gratuities"],"requirements":"Comfortable walking shoes. Modest dress for religious sites.","meetingPoint":"Freetown, exact pickup confirmed on voucher.","image":{"media":"img_074fdb471407d6bf","alt":"A busy market street in central Freetown, Sierra Leone"},"gallery":[{"media":"img_074fdb471407d6bf","alt":"Freetown market street"},{"media":"img_2ff538f47b6ffe72","alt":"Local life"}],"itinerary":[{"day":1,"title":"City orientation","description":"Morning or afternoon circuit of Freetown highlights with a local guide."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb, 1, '63b3aca7-b59a-5bac-9777-ec3fedc2b2db'),
  ('9e5d1df2-d99e-5be7-b07e-6dbeeb8f1a1b', 'tours', 'tacugama-chimpanzee-sanctuary', 1, 'published', '{"slug":"tacugama-chimpanzee-sanctuary","title":"Tacugama Chimpanzee Sanctuary","country":"sierra-leone","circuit":"western-circuit","destinationSlug":"tacugama","duration":"Half day","durationDays":1,"category":"wildlife","difficulty":"easy","groupMin":1,"groupMax":10,"languages":["English"],"summary":"A half-day visit to Tacugama in the forested hills above Freetown, pairing conservation with peninsula views.","highlights":["Sanctuary visit","Forest setting","Conservation briefing"],"inclusions":["Transport from Freetown","Guide","Sanctuary entry"],"exclusions":["Meals","Souvenirs"],"requirements":"Closed shoes. Follow sanctuary viewing rules.","meetingPoint":"Freetown hotel pickup.","image":{"media":"img_5dd1fda75a33445a","alt":"Chimpanzees at Tacugama Chimpanzee Sanctuary near Freetown, Sierra Leone"},"gallery":[{"media":"img_5dd1fda75a33445a","alt":"Tacugama chimpanzees"},{"media":"img_901cfb9f0efd37f4","alt":"Forest path"}],"itinerary":[{"day":1,"title":"Tacugama morning","description":"Drive to the sanctuary, guided visit, return to Freetown."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb, 1, 'a97666ae-3b41-5b01-abbf-ae8f3e82e702'),
