  ('b92b4e31-6245-5b74-a83e-74d10f85ee71', 'tours', 'banana-island', 3, 'published', '{"slug":"banana-island","title":"Banana Island","country":"sierra-leone","circuit":"western-circuit","destinationSlug":"banana-island","duration":"Half day","durationDays":1,"category":"beaches","difficulty":"easy","groupMin":2,"groupMax":10,"languages":["English"],"summary":"The Banana Islands lie off Yawri Bay, south-west of the Freetown Peninsula. Dublin and Ricketts are linked by a stone causeway; Mes-Meheux is uninhabited. Access is by boat from Kent.","highlights":["Boat transfer from Kent","Historical island walk","Lunch and recreation time"],"inclusions":["Transportation (private bus with A/C)","Boat transfer to Banana Island","Lunch and complimentary drinks","English-speaking tour guide","Entrance / site fees","Insurance"],"exclusions":["Personal expenses","Alcoholic drinks","Tips to driver and guide"],"requirements":"Ability to board a small boat. Non-swimmers should say so in advance.","meetingPoint":"State Avenue / Cotton Tree pickup, then Kent Village boat landing, confirmed on voucher.","image":{"media":"img_9c90d5eb4b20c621","alt":"Banana Island off the coast of Sierra Leone"},"gallery":[{"media":"img_9c90d5eb4b20c621","alt":"Banana Island"},{"media":"img_93e145f7529654f0","alt":"Boat crossing"}],"itinerary":[{"day":1,"title":"Freetown to Kent","description":"Set off from State Avenue Cotton Tree to Kent Village."},{"day":1,"title":"Crossing and island","description":"Boat transfer to Banana Island, historical tour, lunch and recreation."},{"day":1,"title":"Return","description":"Depart Kent and transfer to Freetown."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb, 1, '03e65d90-6a44-59b5-90a5-8c2a061289fa'),
