  ('fc81a8f4-b797-5e4c-96b6-fb7ee8a196a4', 'tours', 'bunce-tasso-island', 5, 'published', '{"slug":"bunce-tasso-island","title":"Bunce & Tasso Island","country":"sierra-leone","circuit":"western-circuit","destinationSlug":"bunce-island","duration":"Half day","durationDays":1,"category":"culture","difficulty":"easy","groupMin":2,"groupMax":12,"languages":["English"],"summary":"River journey to Bunce Island’s fort ruins and neighbouring Tasso, history at the heart of the transatlantic story.","highlights":["Fort ruins","River crossing","Guided history"],"inclusions":["Boat","Guide","Site access"],"exclusions":["Meals"],"requirements":"Steady footing on uneven ruins. Sun hat.","meetingPoint":"Freetown waterfront landing, confirmed on booking.","image":{"media":"img_0f71a82d2d92ac0d","alt":"Fortress wall at Bunce Island on the Sierra Leone River"},"gallery":[{"media":"img_0f71a82d2d92ac0d","alt":"River"},{"media":"img_93e145f7529654f0","alt":"Island shore"}],"itinerary":[{"day":1,"title":"River islands","description":"Boat to Bunce and Tasso, guided visit, return."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb, 1, 'c91928c3-79e4-5c23-a3c7-14cfb871b5a6'),
