  ('4fae341f-636a-5725-8f46-90254d2f3655', '6a497420-3cda-5520-90cd-d7779072b2a0', 1, '{"id":"western-circuit","name":"Western Circuit","region":"Freetown Peninsula & Western Area","bestTime":"Year-round","summary":"Freetown’s peninsula beaches, Banana Island, Tacugama Chimpanzee Sanctuary, and Bunce Island: the gateway most travelers meet first.","image":{"media":"img_dcaf420486617fe8","alt":"Tropical coastline with pale sand and turquoise water, editorial stand-in, not an official Tourism Is Life photograph"},"highlights":["Freetown Peninsula beaches","Banana Island","Tacugama","Bunce Island"]}'::jsonb),
