  ('df01ded3-f750-5e4f-9d36-d03f138b1f1b', '886aefb7-103a-5072-8d75-75577b01bf0e', 1, '{"slug":"banana-island","name":"Banana Island","circuit":"western-circuit","country":"sierra-leone","summary":"Three islands off Yawri Bay: Dublin (beaches), Ricketts (forest), and uninhabited Mes-Meheux, settled by freed slaves in the late 18th and 19th centuries.","image":{"media":"img_9c90d5eb4b20c621","alt":"Banana Island, Sierra Leone"}}'::jsonb),
  ('fcf54ef6-12da-5c6c-9d0f-2339c84fccb2', '996374f1-637d-536d-ae3d-e75b7d757654', 1, '{"slug":"freetown-peninsula","name":"Freetown Peninsula","circuit":"western-circuit","country":"sierra-leone","summary":"Eleven beaches along the Western Area peninsula, from River Number Two to Black Johnson.","image":{"media":"img_3485d870528f5864","alt":"A wooden canoe marked \"No 2 River\" on the sand at River Number Two Beach, Sierra Leone"}}'::jsonb),
