  ('43107d9e-89b7-5359-9a16-75991021e657', 'aec6f243-7e07-582d-bad5-78196bdf4251', 1, '{"key":"tour-shared","name":"Questions every tour shows","items":[{"q":"Are prices listed online?","a":"Published rates are quote-based. Request a quote or start a booking enquiry and the team will confirm current pricing."},{"q":"Do I need a yellow fever certificate?","a":"A yellow fever vaccination certificate is required if traveling to and from certain areas. Confirm current entry rules before you fly."},{"q":"Is this a guaranteed departure?","a":"Departures depend on availability and group size. Seats are held for 15 minutes; a booking is confirmed only after a verified payment event."},{"q":"Can I book as a guest?","a":"Yes. An account is optional. After confirmation you can sign in to keep vouchers and future trips in one place."}]}'::jsonb),
  ('63b3aca7-b59a-5bac-9777-ec3fedc2b2db', 'c7155fb7-52a0-5bcb-9ca5-92a938d05708', 1, '{"slug":"freetown-city-tour","title":"Freetown City Tour","country":"sierra-leone","circuit":"western-circuit","destinationSlug":"freetown","duration":"Half day","durationDays":1,"category":"culture","difficulty":"easy","groupMin":1,"groupMax":12,"languages":["English"],"summary":"A guided introduction to Freetown’s Krio heritage, harbour, and city landmarks, the same city tours Tourism Is Life is known for.","highlights":["Krio heritage walk","Harbour and city viewpoints","Local food stop"],"inclusions":[{"claim":"Licensed guide","sourceUrl":"","sourceDate":"","fallback":""},"Ground transport in Freetown","Bottled water"],"exclusions":["Meals not listed","Personal purchases","Gratuities"],"requirements":"Comfortable walking shoes. Modest dress for religious sites.","meetingPoint":"Freetown, exact pickup confirmed on voucher.","image":{"media":"img_074fdb471407d6bf","alt":"A busy market street in central Freetown, Sierra Leone"},"gallery":[{"media":"img_074fdb471407d6bf","alt":"Freetown market street"},{"media":"img_2ff538f47b6ffe72","alt":"Local life"}],"itinerary":[{"day":1,"title":"City orientation","description":"Morning or afternoon circuit of Freetown highlights with a local guide."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('a97666ae-3b41-5b01-abbf-ae8f3e82e702', '9e5d1df2-d99e-5be7-b07e-6dbeeb8f1a1b', 1, '{"slug":"tacugama-chimpanzee-sanctuary","title":"Tacugama Chimpanzee Sanctuary","country":"sierra-leone","circuit":"western-circuit","destinationSlug":"tacugama","duration":"Half day","durationDays":1,"category":"wildlife","difficulty":"easy","groupMin":1,"groupMax":10,"languages":["English"],"summary":"A half-day visit to Tacugama in the forested hills above Freetown, pairing conservation with peninsula views.","highlights":["Sanctuary visit","Forest setting","Conservation briefing"],"inclusions":["Transport from Freetown","Guide","Sanctuary entry"],"exclusions":["Meals","Souvenirs"],"requirements":"Closed shoes. Follow sanctuary viewing rules.","meetingPoint":"Freetown hotel pickup.","image":{"media":"img_5dd1fda75a33445a","alt":"Chimpanzees at Tacugama Chimpanzee Sanctuary near Freetown, Sierra Leone"},"gallery":[{"media":"img_5dd1fda75a33445a","alt":"Tacugama chimpanzees"},{"media":"img_901cfb9f0efd37f4","alt":"Forest path"}],"itinerary":[{"day":1,"title":"Tacugama morning","description":"Drive to the sanctuary, guided visit, return to Freetown."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('ba7787cd-1295-5fc3-9580-5f8571e710ed', 'b7fe41f1-5055-5ff9-a839-d3f1d7994605', 1, '{"slug":"freetown-peninsula","title":"Freetown Peninsula","country":"sierra-leone","circuit":"western-circuit","destinationSlug":"freetown-peninsula","duration":"Day trip","durationDays":1,"category":"beaches","difficulty":"easy","groupMin":1,"groupMax":12,"languages":["English"],"summary":"Beaches of the Western Area peninsula: golden and white-sand coves including well-known stops such as River Number Two and Black Johnson.","highlights":["Peninsula beaches","Atlantic viewpoints","Seafood lunch stop (own account unless quoted)"],"inclusions":["Vehicle and driver-guide","Fuel"],"exclusions":["Meals","Beach club fees if any"],"requirements":"Sun protection. Swim at your own risk.","meetingPoint":"Freetown.","image":{"media":"img_3485d870528f5864","alt":"River Number Two beach on the Freetown Peninsula, Sierra Leone"},"gallery":[{"media":"img_3485d870528f5864","alt":"Peninsula beach"},{"media":"img_dcaf420486617fe8","alt":"Coast"}],"itinerary":[{"day":1,"title":"Peninsula loop","description":"South along the peninsula beaches and return."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('03e65d90-6a44-59b5-90a5-8c2a061289fa', 'b92b4e31-6245-5b74-a83e-74d10f85ee71', 1, '{"slug":"banana-island","title":"Banana Island","country":"sierra-leone","circuit":"western-circuit","destinationSlug":"banana-island","duration":"Half day","durationDays":1,"category":"beaches","difficulty":"easy","groupMin":2,"groupMax":10,"languages":["English"],"summary":"The Banana Islands lie off Yawri Bay, south-west of the Freetown Peninsula. Dublin and Ricketts are linked by a stone causeway; Mes-Meheux is uninhabited. Access is by boat from Kent.","highlights":["Boat transfer from Kent","Historical island walk","Lunch and recreation time"],"inclusions":["Transportation (private bus with A/C)","Boat transfer to Banana Island","Lunch and complimentary drinks","English-speaking tour guide","Entrance / site fees","Insurance"],"exclusions":["Personal expenses","Alcoholic drinks","Tips to driver and guide"],"requirements":"Ability to board a small boat. Non-swimmers should say so in advance.","meetingPoint":"State Avenue / Cotton Tree pickup, then Kent Village boat landing, confirmed on voucher.","image":{"media":"img_9c90d5eb4b20c621","alt":"Banana Island off the coast of Sierra Leone"},"gallery":[{"media":"img_9c90d5eb4b20c621","alt":"Banana Island"},{"media":"img_93e145f7529654f0","alt":"Boat crossing"}],"itinerary":[{"day":1,"title":"Freetown to Kent","description":"Set off from State Avenue Cotton Tree to Kent Village."},{"day":1,"title":"Crossing and island","description":"Boat transfer to Banana Island, historical tour, lunch and recreation."},{"day":1,"title":"Return","description":"Depart Kent and transfer to Freetown."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('569bbb88-0e57-5815-b2b8-ea24048235d2', '95e6753c-ba43-5f12-8a26-a2da6398e0bb', 1, '{"slug":"picket-hill","title":"Picket Hill","country":"sierra-leone","circuit":"western-circuit","destinationSlug":"freetown-peninsula","duration":"Full day","durationDays":1,"category":"adventure","difficulty":"moderate","groupMin":2,"groupMax":8,"languages":["English"],"summary":"A full-day peninsula hike with forest and coastal views above the Western Area.","highlights":["Ridge walking","Forest cover","Peninsula views"],"inclusions":["Guide","Transport to trailhead","Water"],"exclusions":["Meals","Trekking poles"],"requirements":"Moderate fitness. Closed shoes.","meetingPoint":"Freetown.","image":{"media":"img_089c96fda875734e","alt":"Hiking trail in the Loma Mountains Forest Reserve, Sierra Leone, representative of Picket Hill forest trail"},"gallery":[{"media":"img_089c96fda875734e","alt":"Trail"},{"media":"img_e3c729e81afbc790","alt":"Ridge"}],"itinerary":[{"day":1,"title":"Picket Hill hike","description":"Trailhead transfer, hike, return."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('c91928c3-79e4-5c23-a3c7-14cfb871b5a6', 'fc81a8f4-b797-5e4c-96b6-fb7ee8a196a4', 1, '{"slug":"bunce-tasso-island","title":"Bunce & Tasso Island","country":"sierra-leone","circuit":"western-circuit","destinationSlug":"bunce-island","duration":"Half day","durationDays":1,"category":"culture","difficulty":"easy","groupMin":2,"groupMax":12,"languages":["English"],"summary":"River journey to Bunce Island’s fort ruins and neighbouring Tasso, history at the heart of the transatlantic story.","highlights":["Fort ruins","River crossing","Guided history"],"inclusions":["Boat","Guide","Site access"],"exclusions":["Meals"],"requirements":"Steady footing on uneven ruins. Sun hat.","meetingPoint":"Freetown waterfront landing, confirmed on booking.","image":{"media":"img_0f71a82d2d92ac0d","alt":"Fortress wall at Bunce Island on the Sierra Leone River"},"gallery":[{"media":"img_0f71a82d2d92ac0d","alt":"River"},{"media":"img_93e145f7529654f0","alt":"Island shore"}],"itinerary":[{"day":1,"title":"River islands","description":"Boat to Bunce and Tasso, guided visit, return."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('24975553-cdaa-556e-9810-eadd4c8d05a6', '735c4f0a-5820-5ad7-96bd-b7313ffc938c', 1, '{"slug":"bumbuna-waterfalls","title":"Bumbuna Waterfalls","country":"sierra-leone","circuit":"northern-circuit","destinationSlug":"bumbuna-falls","duration":"Day trip","durationDays":1,"category":"adventure","difficulty":"easy","groupMin":2,"groupMax":10,"languages":["English"],"summary":"A northern day trip to Bumbuna Falls through inland countryside.","highlights":["Waterfall viewpoint","Road journey north","Picnic stop"],"inclusions":["Vehicle","Driver-guide"],"exclusions":["Meals","Park fees if applied on the day"],"requirements":"Long driving day. Motion-sickness medication if needed.","meetingPoint":"Freetown.","image":{"media":"img_e4c8ab20049a2f66","alt":"Hills near Bumbuna in northern Sierra Leone, the Bumbuna Falls region"},"gallery":[{"media":"img_e4c8ab20049a2f66","alt":"Falls"},{"media":"img_52b161dc571cf5bb","alt":"Inland road"}],"itinerary":[{"day":1,"title":"Bumbuna out-and-back","description":"Early departure, falls visit, return evening."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('99716518-9581-56d9-9080-54cc4a8e1f79', 'b5a6ff47-4bed-5705-ad14-3da9d2442acf', 1, '{"slug":"wara-wara-mountain","title":"Wara Wara Mountain","country":"sierra-leone","circuit":"northern-circuit","destinationSlug":"wara-wara","duration":"3D / 2N","durationDays":3,"category":"adventure","difficulty":"challenging","groupMin":2,"groupMax":8,"languages":["English"],"summary":"A three-day highland trek in Koinadugu District’s Wara Wara range.","highlights":["Mountain trekking","Village stays","Northern highlands"],"inclusions":["Guide","Camping or simple lodge as quoted","Ground transport"],"exclusions":["International flights","Travel insurance","Sleeping bag unless quoted"],"requirements":"Good fitness. Prior trekking experience recommended.","meetingPoint":"Freetown or Makeni, confirmed on itinerary.","image":{"media":"img_ca592deae3086822","alt":"Wara Wara Mountains near Bafodia in northern Sierra Leone"},"gallery":[{"media":"img_ca592deae3086822","alt":"Mountains"},{"media":"img_bddfa9be0cabecdb","alt":"Highland village"}],"itinerary":[{"day":1,"title":"Travel north","description":"Transfer into Koinadugu and evening briefing."},{"day":2,"title":"Wara Wara trek","description":"Full trekking day with picnic lunch."},{"day":3,"title":"Descent and return","description":"Morning trail and road return."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
