  ('9099c147-13d4-5d66-8f8c-00817b6b5935', '8b08d2d5-69c9-5069-a0c1-ddf22879ceb8', 1, '{"slug":"bintumani-mountain","title":"Bintumani Mountain","country":"sierra-leone","circuit":"northern-circuit","destinationSlug":"bintumani","duration":"4D / 3N","durationDays":4,"category":"adventure","difficulty":"challenging","groupMin":2,"groupMax":8,"languages":["English"],"summary":"Expedition to Mount Bintumani, the highest peak in Sierra Leone, a signature Tourism Is Life trek.","highlights":["Summit attempt","Loma Mountains","Remote camping"],"inclusions":["Mountain guide","Porters as quoted","Camping kit as quoted","Transport"],"exclusions":["Personal trekking gear","Insurance"],"requirements":"High fitness. Altitude and remote conditions. Travel insurance required.","meetingPoint":"Freetown.","image":{"media":"img_e3c729e81afbc790","alt":"Mount Bintumani, the highest peak in Sierra Leone and the Loma Mountains"},"gallery":[{"media":"img_e3c729e81afbc790","alt":"Peak"},{"media":"img_5ebe93e7ef8e3465","alt":"Approach trail"}],"itinerary":[{"day":1,"title":"Approach","description":"Road to the Loma foothills."},{"day":2,"title":"Ascent camp","description":"Trek to high camp."},{"day":3,"title":"Summit window","description":"Summit attempt and descent."},{"day":4,"title":"Return","description":"Road back to Freetown."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('97252b12-2bac-5e48-b770-66fddac84a26', 'e9328849-208d-5d2f-a7f5-264164769093', 1, '{"slug":"bo-city","title":"Bo City","country":"sierra-leone","circuit":"southern-circuit","destinationSlug":"bo","duration":"3D / 2N","durationDays":3,"category":"culture","difficulty":"easy","groupMin":2,"groupMax":10,"languages":["English"],"summary":"A three-day stay in Bo, Sierra Leone’s second city and southern gateway.","highlights":["Bo city","Southern Province context","Link to Tiwai on request"],"inclusions":["Transport","Guide","Accommodation as quoted"],"exclusions":["Meals not listed"],"requirements":"None beyond standard travel fitness.","meetingPoint":"Freetown.","image":{"media":"img_401bae1b1ef19891","alt":"Rice cultivation in the inland valleys around Bo, Sierra Leone"},"gallery":[{"media":"img_401bae1b1ef19891","alt":"Bo"},{"media":"img_2ff538f47b6ffe72","alt":"Markets"}],"itinerary":[{"day":1,"title":"South to Bo","description":"Road transfer and evening walk."},{"day":2,"title":"Bo and surroundings","description":"City and nearby visits."},{"day":3,"title":"Return","description":"Drive to Freetown."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('bd0d7aed-fb91-52ab-85cb-41fe47d9815b', 'f04011cb-14fa-5938-a636-1c0b18b4eda4', 1, '{"slug":"tiwai-island","title":"Tiwai Island Wildlife Sanctuary","country":"sierra-leone","circuit":"southern-circuit","destinationSlug":"tiwai","duration":"3D / 2N","durationDays":3,"category":"wildlife","difficulty":"moderate","groupMin":2,"groupMax":8,"languages":["English"],"summary":"Two nights on Tiwai Island in the Moa River, with primates, forest walks, and night sounds of the southern rainforest.","highlights":["Island sanctuary","Primate walks","River setting"],"inclusions":["Transport","Canoe transfer","Simple island lodging as quoted","Guided walks"],"exclusions":["Alcohol","Travel insurance"],"requirements":"Ability to walk forest trails. Insect protection.","meetingPoint":"Freetown or Bo.","image":{"media":"img_901cfb9f0efd37f4","alt":"Tiwai Island wildlife sanctuary in the Moa River, Sierra Leone"},"gallery":[{"media":"img_901cfb9f0efd37f4","alt":"Forest"},{"media":"img_5dd1fda75a33445a","alt":"Wildlife habitat"}],"itinerary":[{"day":1,"title":"To Tiwai","description":"Road south and canoe to the island."},{"day":2,"title":"Sanctuary walks","description":"Dawn and afternoon guided walks."},{"day":3,"title":"Return","description":"Leave the island and drive north."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('772ded86-9a74-5a58-b622-4a60eebb06a1', '36c223fd-340c-501c-b161-585b303f6ec2', 1, '{"slug":"turtle-island","title":"Turtle Islands","country":"sierra-leone","circuit":"southern-circuit","destinationSlug":"turtle-islands","duration":"3D / 2N","durationDays":3,"category":"beaches","difficulty":"moderate","groupMin":2,"groupMax":10,"languages":["English"],"summary":"A three-day expedition to the Turtle Islands: remote beaches and fishing communities off the southern coast.","highlights":["Archipelago boat travel","Remote beaches","Community visit"],"inclusions":["Boat","Guide","Camping or simple lodging as quoted"],"exclusions":["Sleeping bag unless quoted","Meals not listed"],"requirements":"Comfortable on small boats. Flexible timing with tides and weather.","meetingPoint":"Southern coast landing, confirmed on itinerary.","image":{"media":"img_042bf452aef2649c","alt":"Tokeh Beach coastline in Sierra Leone, representative of remote island beaches"},"gallery":[{"media":"img_042bf452aef2649c","alt":"Islands"},{"media":"img_93e145f7529654f0","alt":"Beach"}],"itinerary":[{"day":1,"title":"To the islands","description":"Boat out and camp or lodge."},{"day":2,"title":"Island time","description":"Beaches, snorkelling if conditions allow, village visit."},{"day":3,"title":"Return","description":"Boat back to the mainland."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('e9a38b38-70ec-5f6e-9557-a9afefb13f7d', 'e25e365c-70f0-5250-bdc4-63480fa1ad13', 1, '{"slug":"gola-rainforest","title":"Gola Rainforest","country":"sierra-leone","circuit":"eastern-circuit","destinationSlug":"gola","duration":"3D / 2N","durationDays":3,"category":"wildlife","difficulty":"moderate","groupMin":2,"groupMax":8,"languages":["English"],"summary":"Three days in Gola Rainforest National Park, in pygmy hippo country, with hornbills and one of West Africa’s last lowland rainforests.","highlights":["Rainforest walks","Birding","Park community context"],"inclusions":["Park arrangements as quoted","Guide","Transport","Simple lodging"],"exclusions":["Specialist birding gear","Insurance"],"requirements":"Forest walking fitness. Rain jacket year-round.","meetingPoint":"Freetown or Kenema.","image":{"media":"img_3ee29014aa4978c5","alt":"Gola Rainforest National Park landscape, Sierra Leone"},"gallery":[{"media":"img_3ee29014aa4978c5","alt":"Rainforest canopy"},{"media":"img_5dd1fda75a33445a","alt":"Forest wildlife"}],"itinerary":[{"day":1,"title":"East to Gola","description":"Road to the park edge and evening briefing."},{"day":2,"title":"Forest day","description":"Guided walks and river time."},{"day":3,"title":"Return","description":"Drive west."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('603ebbe5-5948-5da7-af29-d3f473e1a428', '00f383ff-3370-5f52-a89d-a40e520b8cfe', 1, '{"slug":"kenema-city","title":"Kenema City","country":"sierra-leone","circuit":"eastern-circuit","destinationSlug":"kenema","duration":"3D / 2N","durationDays":3,"category":"culture","difficulty":"easy","groupMin":2,"groupMax":10,"languages":["English"],"summary":"Three days in Kenema District, the eastern hub for Gola and diamond-country travel.","highlights":["Kenema town","Eastern Province markets","Optional Gola day on request"],"inclusions":["Transport","Guide","Accommodation as quoted"],"exclusions":["Meals not listed"],"requirements":"None beyond standard travel fitness.","meetingPoint":"Freetown.","image":{"media":"img_5711f12c75345b60","alt":"Aerial view of Kenema, Sierra Leone"},"gallery":[{"media":"img_5711f12c75345b60","alt":"Kenema town"},{"media":"img_3cdcc1daf2d26b2f","alt":"East forest edge"}],"itinerary":[{"day":1,"title":"To Kenema","description":"Long road east."},{"day":2,"title":"District day","description":"Town and nearby visits."},{"day":3,"title":"Return","description":"Drive to Freetown."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('b5608920-7330-5031-8a17-348d59577d2b', '98d29974-b189-5c79-b812-db9bf92eb7d1', 1, '{"slug":"kono-b-kongo","title":"Kono to B Kongo","country":"sierra-leone","circuit":"eastern-circuit","destinationSlug":"kono","duration":"3D / 2N","durationDays":3,"category":"culture","difficulty":"moderate","groupMin":2,"groupMax":8,"languages":["English"],"summary":"A three-day journey into Kono District, including B Kongo, eastern Sierra Leone beyond the tourist trail.","highlights":["Kono District","Community visits","Eastern highlands context"],"inclusions":["Transport","Guide","Lodging as quoted"],"exclusions":["Unlisted meals"],"requirements":"Flexible with basic lodging. Long road days.","meetingPoint":"Freetown or Kenema.","image":{"media":"img_8cbb03f35dbac0b9","alt":"Koidu market in Kono District, Sierra Leone"},"gallery":[{"media":"img_8cbb03f35dbac0b9","alt":"Landscape"},{"media":"img_2ff538f47b6ffe72","alt":"Community"}],"itinerary":[{"day":1,"title":"Into Kono","description":"Road to Koidu / Kono."},{"day":2,"title":"B Kongo","description":"District visits as conditions allow."},{"day":3,"title":"Return","description":"Drive west."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('d40a2328-ae70-50ed-83be-3752dd780e02', 'f3d15986-650a-5e8c-b3a0-3cf1212e225e', 1, '{"slug":"fouta-djallon-highlands","title":"Fouta Djallon Highlands Trek","country":"guinea","circuit":"northern-circuit","destinationSlug":"freetown","duration":"Custom","durationDays":7,"category":"adventure","difficulty":"challenging","groupMin":4,"groupMax":12,"languages":["English","French"],"summary":"Custom highland trekking in Guinea’s Fouta Djallon. Quote-only. Logistics confirmed per departure.","highlights":["Highland trails","Waterfalls","Fula highlands"],"inclusions":["Quoted per itinerary"],"exclusions":["Visas","International flights"],"requirements":"Valid Guinea entry. Trekking fitness.","meetingPoint":"Conakry or overland from Sierra Leone, quoted.","image":{"media":"img_e3c729e81afbc790","alt":"Highland plateau, editorial stand-in"},"gallery":[{"media":"img_e3c729e81afbc790","alt":"Highlands"}],"itinerary":[{"day":1,"title":"Custom itinerary","description":"Built after a quote request."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('035b9176-26ac-5c63-b543-940e3af15c6a', '4591dde5-c5e9-5b49-8e9b-f69842a4b59c', 1, '{"slug":"sapo-national-park","title":"Sapo National Park Safari","country":"liberia","circuit":"southern-circuit","destinationSlug":"tiwai","duration":"Custom","durationDays":5,"category":"wildlife","difficulty":"challenging","groupMin":4,"groupMax":10,"languages":["English"],"summary":"Custom Liberia programme centred on Sapo National Park. Quote-only multi-country or Liberia-only.","highlights":["Sapo rainforest","Park logistics","Monrovia add-on on request"],"inclusions":["Quoted per itinerary"],"exclusions":["Visas","Flights"],"requirements":"Liberia entry formalities. Remote-travel fitness.","meetingPoint":"Monrovia, quoted.","image":{"media":"img_3cdcc1daf2d26b2f","alt":"Liberian rainforest, editorial stand-in"},"gallery":[{"media":"img_3cdcc1daf2d26b2f","alt":"Forest"}],"itinerary":[{"day":1,"title":"Custom itinerary","description":"Built after a quote request."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('0cb9bd23-f940-52dd-85d6-43bcec58dd25', '590f3aa3-4770-5b18-af5a-12021186d103', 1, '{"slug":"mano-river-triangle","title":"Mano River Triangle","country":"west-africa","circuit":"southern-circuit","destinationSlug":"gola","duration":"Custom · typically 13 days · 3 countries","durationDays":13,"category":"culture","difficulty":"moderate","groupMin":6,"groupMax":16,"languages":["English","French"],"summary":"A cross-border circuit through Guinea, Sierra Leone, and Liberia, the three countries that meet at the Mano River. One route, three national guides, and a single DMC coordinating the handover at each border.","highlights":["Conakry, Freetown, and Monrovia in one itinerary","A guide change at each land border, not a single guide guessing their way through three countries","Waterfalls, island crossings, and city stops rather than long transit days back to back"],"inclusions":["Quoted per group"],"exclusions":["International flights","Visas","Travel insurance and yellow fever vaccination"],"requirements":"Entry requirements for Guinea, Sierra Leone, and Liberia. Confirm current visa rules before booking flights. Group passport copies in advance.","meetingPoint":"Conakry, Freetown, or Monrovia, set by the direction of travel and confirmed in the quote.","image":{"media":"img_089c96fda875734e","alt":"Forested border hills typical of the Mano River Triangle region, editorial stand-in"},"gallery":[{"media":"img_089c96fda875734e","alt":"Forested hill country near the border"},{"media":"img_3ee29014aa4978c5","alt":"Rainforest along the Sierra Leone–Liberia border"}],"itinerary":[{"day":1,"title":"Arrival in Conakry","description":"Meet and assist at Gbessia International Airport, transfer into the city."},{"day":2,"title":"Conakry city tour","description":"National Museum, the market, the cathedral, and the central mosque."},{"day":3,"title":"Îles de Los","description":"Boat transfer to the small island group off Conakry: Tamara, Kassa, and Roume."},{"day":4,"title":"Kindia and Kilissi","description":"Mount Gangan and the Kilissi waterfall, an ecotourism site with two natural swimming pools."},{"day":5,"title":"Border crossing into Sierra Leone","description":"Guinean and Sierra Leonean guides hand over at the border."},{"day":6,"title":"Bunce Island","description":"The former slave-trading fort on the Sierra Leone River, a national monument since 1948."},{"day":7,"title":"Banana Island","description":"Boat crossing via Kent to the island''s former plantation settlement."},{"day":8,"title":"Bo","description":"Sierra Leone''s second city: markets and daily life away from the capital."},{"day":9,"title":"Kenema, then on to Liberia","description":"The Eastern Province''s diamond-district hub, then the road to Monrovia via Zimmi."},{"day":10,"title":"Robertsport","description":"The WWII Allied submarine base site, a fishing village, and (sea conditions allowing) a surf break."},{"day":11,"title":"Monrovia","description":"A city tour taking in Waterside Market and the West Point neighbourhood."},{"day":12,"title":"Providence Island","description":"Where Liberia''s early settlers first landed on the Mesurado River, and the Centennial Pavilion."},{"day":13,"title":"Libassa and departure","description":"A coastal morning before the transfer to the airport."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('76a5cac1-b142-5ec1-9481-1b92acd3e12f', '98e9b4b2-794a-5e99-8b19-cd69e7909518', 1, '{"slug":"heart-of-sierra-leone-expedition","title":"Heart of Sierra Leone Expedition","country":"sierra-leone","circuit":"western-circuit","destinationSlug":"freetown","duration":"11 days / 10 nights","durationDays":11,"category":"culture","difficulty":"moderate","groupMin":0,"groupMax":0,"languages":["English"],"summary":"Eleven days across the country''s headline sites: Freetown''s museums and monuments, Bunce and Tasso Islands, Tacugama, Tiwai Island on the Moa River, the peninsula beaches, and Banana Island.","highlights":["Bunce Island, the largest British slave castle on the Rice Coast, founded around 1670","Tiwai Island and the heritage trail, including Boma village and Nainiahun","Tacugama Chimpanzee Sanctuary, a 100-acre reserve established in 1995","Peninsula beaches and two nights on Banana Island"],"inclusions":["Accommodation","English-speaking tour guides","Entrance and site fees","Meals as outlined in the itinerary","Transportation (private bus with air conditioning)","Entry visas","Security fees"],"exclusions":["Airfares","Travel insurance and yellow fever vaccination","Meals not listed","Tips and gratuities to driver and guide","Change and cancellation fees","Communication cost"],"requirements":"Travel insurance and yellow fever vaccination are arranged by the traveller. Entry visas are included and handled by the desk.","meetingPoint":"Lungi International Airport, with meet and assist before the boat transfer to Freetown.","image":{"media":"img_9c90d5eb4b20c621","alt":"Banana Island, Sierra Leone"},"gallery":[{"media":"img_72510ed289e3e016","alt":"Bunce Island on the Sierra Leone River"},{"media":"img_5dd1fda75a33445a","alt":"Chimpanzee at Tacugama Chimpanzee Sanctuary"},{"media":"img_901cfb9f0efd37f4","alt":"Forest path on Tiwai Island"},{"media":"img_3485d870528f5864","alt":"River Number Two Beach, Sierra Leone"}],"itinerary":[{"day":1,"title":"Arrival","description":"Met and assisted at Lungi International Airport, then transferred to Freetown by boat. Overnight at Country Lodge Complex."},{"day":2,"title":"Freetown city tour","description":"The Railway Museum, Old Fourah Bay College, the site of the recently fallen Cotton Tree, the Peace and Cultural Monument, the National Museum, the Sierra Leone Peace Museum, and the Gateway to the King''s Yard. Lunch at the rooftop restaurant of the country''s tallest building, passing State House and the Parliament building."},{"day":3,"title":"Bunce Island and Tasso Island","description":"Bunce Island was the largest British slave castle on the Rice Coast of West Africa. Founded around 1670, it exported tens of thousands of African captives to North America and the West Indies until Parliament closed it in 1807. A four and a half hour return boat ride plus the tour, followed by Tasso Island."},{"day":4,"title":"Tacugama","description":"Tacugama Chimpanzee Sanctuary, about 40 minutes from central Freetown, rescues and rehabilitates orphaned and abandoned chimpanzees. Established in 1995, the chimps live semi-wild across a 100-acre reserve."},{"day":5,"title":"Tacugama to Tiwai Island","description":"Travel to Tiwai by way of the heritage trail, stopping at Boma village on the Moa River near the small island of Nainiati. Boma is the only community on the trail led by a woman chief."},{"day":6,"title":"Tiwai Island","description":"Walk to Nainiahun along bush trails through rice, cocoa and kola nut plantations. Nainiahun means Sand Village in Mende and is a site of artisanal diamond mining. Visit Kote Wulehun, the cultural heritage site the community shares with visitors."},{"day":7,"title":"Tiwai Island to Tokeh","description":"An early start into dense forest to look for chimpanzees and other monkey species, some 135 bird species, and the occasional crocodile, before returning to camp for breakfast and departing for the coast."},{"day":8,"title":"Tokeh and the peninsula beaches","description":"River Number Two for sunbathing, with the option of a 25-minute walk along the white sand, and visits to other peninsula beaches."},{"day":9,"title":"Tokeh to Banana Island","description":"An early departure by boat to Banana Island, a former slave island with remnants of Portuguese infrastructure from the 1800s and home to a Krio community. Time with locals and water activities."},{"day":10,"title":"Banana Island","description":"Snorkelling, watersports and sport fishing."},{"day":11,"title":"Departure","description":"Depart Banana Island by sea coach."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('7ace8f73-e827-5587-946e-cc49e3c2f8c1', '883295e1-5d24-5751-bc88-596c93e3cd4c', 1, '{"slug":"sierra-breeze-adventure","title":"Sierra Breeze Adventure","country":"sierra-leone","circuit":"northern-circuit","destinationSlug":"makeni","duration":"9 days / 8 nights","durationDays":9,"category":"culture","difficulty":"moderate","groupMin":0,"groupMax":0,"languages":["English"],"summary":"Nine days from Freetown into the north and south: Rogbonko village, the Wara Wara mountains at Kabala, agro-tourism at Senekedugu, Bo''s markets, Tiwai Island, and Banana Island.","highlights":["Rogbonko village, paying homage to the chief and joining local cooking and basket making","Wara Wara mountain at Kabala, plus a local cotton weaver and an evening folklore performance","Agro-tourism at Senekedugu and the gold mines around Kabala town","A dawn rainforest walk on Tiwai in search of pygmy hippos"],"inclusions":["Accommodation","English-speaking tour guides","Entrance and site fees","Meals as outlined in the itinerary","Transportation (private bus with air conditioning)","Security fees","Sea coach","Entry visas"],"exclusions":["Airfares","Travel insurance and yellow fever vaccination","Meals not listed","Tips and gratuities to driver and guide","Change and cancellation fees","Communication cost"],"requirements":"Travel insurance and yellow fever vaccination are arranged by the traveller. Entry visas are included and handled by the desk.","meetingPoint":"Lungi International Airport, with meet and assist before the boat transfer to Freetown.","image":{"media":"img_ca592deae3086822","alt":"The Wara Wara Mountains in Koinadugu District, Sierra Leone"},"gallery":[{"media":"img_796e4fc67c90e376","alt":"Kabala, Koinadugu District, Sierra Leone"},{"media":"img_bddfa9be0cabecdb","alt":"Makeni, Northern Province, Sierra Leone"},{"media":"img_401bae1b1ef19891","alt":"Rice farming in the countryside around Bo, Sierra Leone"},{"media":"img_901cfb9f0efd37f4","alt":"Forest path on Tiwai Island"}],"itinerary":[{"day":1,"title":"Arrival","description":"Met and assisted at Lungi International Airport, then transferred to Freetown by boat."},{"day":2,"title":"Freetown city tour and Tacugama","description":"The Railway Museum, Old Fourah Bay College, the Cotton Tree site, the Peace and Cultural Monument, the National Museum, the Peace Museum and the Gateway to the King''s Yard, followed by Tacugama Chimpanzee Sanctuary, about 40 minutes from central Freetown."},{"day":3,"title":"Makeni and Rogbonko village","description":"Drive to Makeni for a city tour, then on to Rogbonko village to visit the chief and pay homage. A working village where visitors join in cooking, basket making and other daily activities, returning to Makeni for the night."},{"day":4,"title":"Makeni to Kabala","description":"An excursion to see Wara Wara mountain, where huge rocks merge into towering formations. In the evening, a visit to a local cotton weaver to take part in the process, followed after dinner by a folklore and cultural dance performance."},{"day":5,"title":"Kabala and Senekedugu","description":"The gold mines around Kabala town show how mining works here. An early drive three miles to Senekedugu for agro-tourism, welcomed by the chief, with a visit to the vegetable plantations."},{"day":6,"title":"Kabala to Bo","description":"Drive to Bo, the second capital, for the bustling city, the local market and a gari production site."},{"day":7,"title":"Bo to Tiwai Island","description":"Shoes off as a sign of respect before entering, then a locally sourced meal under the palms and a walk to the banks of the Moa River, where a boat crosses to Tiwai. In the early evening, a boat ride upriver for a chance of seeing a pygmy hippo."},{"day":8,"title":"Tiwai Island to Banana Island","description":"A pre-dawn walk through the rainforest in search of pygmy hippos, which come ashore at night to graze. Later, on to Banana Island via Kent beach, a former slave island with remnants of Portuguese infrastructure from the 1800s and home to a Krio community."},{"day":9,"title":"Departure","description":"Depart Banana Island by sea coach for the airport."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb),
  ('a24a2a01-f264-5b0f-8a81-d8d0a5a03ba1', '22643877-d657-5e19-8c6a-9f6092be73d6', 1, '{"slug":"taste-of-west-africa","title":"A Taste of West Africa","country":"west-africa","circuit":"southern-circuit","destinationSlug":"freetown","duration":"44 days · 8 countries · 3 joinable segments","durationDays":44,"category":"culture","difficulty":"challenging","groupMin":0,"groupMax":0,"languages":["English"],"summary":"A 44-day overland route across eight West African countries, run with Oasis Overland. It splits into three segments that can be joined separately: Benin, Togo and Ghana; Ghana through Ivory Coast and Liberia to Sierra Leone; then Sierra Leone north to Senegal.","highlights":["Trip 1, 11 days: Benin, Togo and Ghana, including the Dahomey royal palaces at Abomey and the Koutammakou landscape","Trip 2, 18 days: Ghana to Sierra Leone, including Cape Coast and Elmina Castles, Kakum, Mount Nimba and Tiwai Island","Trip 3, 16 days: Sierra Leone to Senegal, including the Fouta Djallon, the Bijagós Archipelago and Gorée Island","Border crossings, visas support and guides coordinated across all eight countries"],"inclusions":["English-speaking tour guides throughout","All entry and site fees for activities listed in the itinerary","Accommodation for every night of the tour","Daily breakfast","Ground and water transport (private air-conditioned vehicle and boat transfers)","Security fees, airport transfers and border arrangements"],"exclusions":["Visas (visa support and guidance are provided, but visa cost is not included)"],"requirements":"Visa requirements vary by nationality and change over time. The desk provides guidance and support through the application process for each country on the route.","meetingPoint":"Cotonou, Benin for the full route. Trip 2 begins in Accra, Ghana and Trip 3 begins in Freetown.","image":{"media":"img_089c96fda875734e","alt":"Forested hill country of the kind crossed on the West Africa overland route"},"gallery":[{"media":"img_901cfb9f0efd37f4","alt":"Forest path on Tiwai Island, Sierra Leone"},{"media":"img_9c90d5eb4b20c621","alt":"Banana Island, Sierra Leone"},{"media":"img_5dd1fda75a33445a","alt":"Chimpanzee at Tacugama Chimpanzee Sanctuary"}],"itinerary":[{"day":1,"title":"Arrive in Cotonou, Benin","description":"Trip 1 begins."},{"day":2,"title":"Cotonou and Porto-Novo","description":"The port city and the historical capital."},{"day":3,"title":"Abomey","description":"The royal palaces of the Dahomey Kingdom, a UNESCO World Heritage Site."},{"day":4,"title":"Koutammakou landscape, Togo","description":"Cross into Togo for the mud-tower houses of the Batammariba people."},{"day":5,"title":"Atakpamé","description":"A scenic drive through Togo''s Plateaux Region."},{"day":6,"title":"Lomé, Togo","description":"The coastal capital, its markets and monumental squares."},{"day":7,"title":"Wli Waterfalls, Ghana","description":"Cross into Ghana toward the tallest waterfall in West Africa."},{"day":8,"title":"Hike and wildlife","description":"Trek to the Wli Waterfalls and visit a sacred monkey sanctuary."},{"day":9,"title":"Akosombo Dam","description":"The dam that created Lake Volta."},{"day":10,"title":"Accra","description":"Ghana''s capital."},{"day":11,"title":"Accra","description":"Trip 1 concludes and Trip 2 begins."},{"day":12,"title":"Accra city tour","description":"The Kwame Nkrumah Mausoleum, Makola Market and Labadi Beach."},{"day":13,"title":"Cape Coast","description":"Cape Coast Castle."},{"day":14,"title":"Elmina Castle","description":"The first European trading post in sub-Saharan Africa."},{"day":15,"title":"Kakum National Park","description":"The rainforest canopy walkway."},{"day":16,"title":"Grand-Bassam, Ivory Coast","description":"Cross into Côte d''Ivoire to this colonial beach town."},{"day":17,"title":"Abidjan","description":"St Paul''s Cathedral and the Plateau district."},{"day":18,"title":"Yamoussoukro","description":"The Basilica of Our Lady of Peace."},{"day":19,"title":"Man","description":"The 18 Mountains region and its waterfalls."},{"day":20,"title":"Cross into Liberia","description":"Arrive in the border city of Ganta."},{"day":21,"title":"Mount Nimba","description":"The UNESCO-listed mountain range."},{"day":22,"title":"Monrovia","description":"A guided tour of Liberia''s capital."},{"day":23,"title":"Robertsport","description":"Surfing and a historic WWII submarine base."},{"day":24,"title":"Tiwai Island, Sierra Leone","description":"Cross into Sierra Leone and travel to the wildlife sanctuary."},{"day":25,"title":"Tiwai Island","description":"Guided walks in search of the pygmy hippopotamus and other rainforest wildlife."},{"day":26,"title":"Banana Island","description":"A boat trip to the island community and its Krio heritage."},{"day":27,"title":"Freetown and Tacugama","description":"A Freetown city tour followed by Tacugama Chimpanzee Sanctuary."},{"day":28,"title":"Freetown","description":"Trip 2 concludes."},{"day":29,"title":"Freetown","description":"Trip 3 begins."},{"day":30,"title":"Cross into Guinea","description":"Arrive in Conakry."},{"day":31,"title":"Kindia and Voile de la Mariée","description":"The Bridal Veil waterfalls."},{"day":32,"title":"Labé","description":"Into the Fouta Djallon highlands."},{"day":34,"title":"Cross into Guinea-Bissau","description":"Through the countryside to Gabu."},{"day":35,"title":"Bissau","description":"A guided tour of the capital."},{"day":36,"title":"Bijagós Archipelago","description":"A UNESCO Biosphere Reserve, subject to boat schedules."},{"day":37,"title":"Cross into The Gambia","description":"Over the Senegambia Bridge, with local markets."},{"day":38,"title":"Janjanbureh and Baboon Islands","description":"A boat safari on the River Gambia for chimpanzees, hippos and baboons."},{"day":39,"title":"Serekunda","description":"The Kachikally Crocodile Pool and local markets."},{"day":40,"title":"Cross into Senegal and Shell Island","description":"Toubacouta and the shell-covered Fadiouth Island."},{"day":41,"title":"Dakar","description":"Senegal''s capital."},{"day":42,"title":"Gorée Island","description":"The House of Slaves."},{"day":43,"title":"Pink Lake","description":"Lac Rose."},{"day":44,"title":"Dakar","description":"Trip 3 and the full itinerary conclude."}],"faqGroup":"tour-shared","faqs":[]}'::jsonb)
